'use client';

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Center, ContactShadows, Environment, Float, PresentationControls } from '@react-three/drei';
import * as THREE from 'three';

export default function SignatureObject() {
  const meshRef = useRef<THREE.Group>(null);

  // Subtle scroll/time driven rotation
  useFrame((state) => {
    if (meshRef.current) {
      // Very restrained rotation, mostly drifting
      meshRef.current.rotation.y = Math.sin(state.clock.elapsedTime * 0.2) * 0.1;
      meshRef.current.rotation.x = Math.cos(state.clock.elapsedTime * 0.2) * 0.05;
    }
  });

  return (
    <>
      <color attach="background" args={['#F1EFEA']} />
      
      {/* Product Photography Lighting Setup */}
      <ambientLight intensity={0.5} />
      {/* Key Light */}
      <directionalLight 
        position={[5, 5, 5]} 
        intensity={2} 
        castShadow 
        shadow-mapSize={1024}
      />
      {/* Soft Fill / Bounce */}
      <directionalLight 
        position={[-5, 3, -5]} 
        intensity={0.5} 
        color="#a5b4fc" 
      />

      {/* The Object — Abstract 'S' Extrusion */}
      <PresentationControls
        global
        snap={true}
        rotation={[0, 0.3, 0]}
        polar={[-Math.PI / 3, Math.PI / 3]}
        azimuth={[-Math.PI / 1.4, Math.PI / 2]}
      >
        <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.5}>
          <Center>
            <group ref={meshRef}>
              {/* Central Block */}
              <mesh castShadow receiveShadow>
                {/* Abstract 'S' shape approximation using basic geometry for now */}
                <boxGeometry args={[2, 3, 0.8]} />
                <meshStandardMaterial 
                  color="#A9A296" // Alloy
                  metalness={0.6}
                  roughness={0.2}
                />
              </mesh>
              {/* Recessed Cobalt Accent */}
              <mesh position={[0, 0, 0.41]}>
                <planeGeometry args={[1.5, 2.5]} />
                <meshBasicMaterial color="#3346FF" /> {/* Signal */}
              </mesh>
            </group>
          </Center>
        </Float>
      </PresentationControls>

      {/* Soft Contact Shadow on the canvas backdrop */}
      <ContactShadows 
        position={[0, -2, 0]} 
        opacity={0.4} 
        scale={10} 
        blur={2} 
        far={4} 
        color="#17161A" 
      />
      
      <Environment preset="city" />
    </>
  );
}
